    public static function boot(): void {
        add_action('init', [__CLASS__, 'ensure_pages'], 110);
        add_action('wp_enqueue_scripts', [__CLASS__, 'assets'], 1);
        add_action('template_redirect', [__CLASS__, 'render'], 0);
    }

    public static function ensure_pages(): void {
        if ((string)get_option(self::OPTION_VERSION) === self::VERSION) { return; }
        $ids = [];
        foreach (self::$pages as $slug=>$config) {
            $existing = get_page_by_path($slug, OBJECT, 'page');
            if ($existing && $existing->post_status !== 'trash') { $ids[$slug]=(int)$existing->ID; continue; }
            $id = wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$config['title'],'post_name'=>$slug,'post_content'=>''], true);
            if (!is_wp_error($id)) { $ids[$slug]=(int)$id; }
        }
        foreach (self::$pages as $slug=>$config) {
            $parent=(string)$config['parent'];
            if ($parent==='' || empty($ids[$slug]) || empty($ids[$parent])) { continue; }
            if ((int)wp_get_post_parent_id($ids[$slug]) !== (int)$ids[$parent]) { wp_update_post(['ID'=>$ids[$slug],'post_parent'=>$ids[$parent]]); }
        }
        update_option(self::OPTION_VERSION,self::VERSION,false);
        flush_rewrite_rules(false);
    }

    public static function assets(): void {
        $managed = is_front_page() || (is_page() && isset(self::$pages[(string)get_post_field('post_name', get_queried_object_id())]));
        if (!$managed) { return; }
        wp_register_style('bizrise-ddg-full-pages', false, [], self::VERSION);
        wp_enqueue_style('bizrise-ddg-full-pages');
        wp_add_inline_style('bizrise-ddg-full-pages', self::css());
    }

    public static function render(): void {
        if (is_admin() || is_feed() || wp_doing_ajax()) { return; }
        if (is_singular(['bizrise_product','ddg_product','product'])) { return; }
        if (is_front_page()) { self::output('home','home'); }
        if (!is_page()) { return; }
        $post = get_queried_object();
        if (!$post instanceof WP_Post) { return; }
        $slug=(string)$post->post_name;
        if (!isset(self::$pages[$slug])) { return; }
        self::output($slug,(string)self::$pages[$slug]['type']);
    }

    private static function output(string $slug,string $type): void {
        status_header(200);
        get_header();
        echo '<main id="primary" class="ddgx ddgx--'.esc_attr($type).'">';
        if ($slug==='home') { self::home(); }
        elseif ($type==='brand') { self::brand($slug); }
        else { self::page($slug,$type); }
        echo '</main>';
        get_footer();
        exit;
    }

