    private static function page(string $slug,string $type): void {
        $map = self::content_map();
        $data = $map[$slug] ?? ['eyebrow'=>'ĐĂNG DƯƠNG GROUP','title'=>self::$pages[$slug]['title'] ?? 'Đăng Dương Group','lead'=>'Nội dung đang được hoàn thiện theo hệ thống trải nghiệm Đăng Dương Group.'];
        self::hero($data['eyebrow'],$data['title'],$data['lead'],$data['cta'] ?? '',$data['cta_url'] ?? '',$slug);
        switch ($type) {
            case 'about': self::about_sections(); break; case 'story': self::story_sections(); break; case 'vision': self::vision_sections(); break; case 'values': self::values_sections(); break; case 'media': self::media_sections(); break;
            case 'capability': self::capability_sections(); break; case 'rd': self::rd_sections(); break; case 'formula': self::formula_sections(); break; case 'quality': self::quality_sections(); break; case 'factory': self::factory_sections(); break; case 'manufacturing': self::manufacturing_sections(); break; case 'oem': self::oem_sections(); break; case 'process': self::process_sections(); break;
            case 'brands': self::brands_hub(); break; case 'routine-hub': self::routine_hub(); break; case 'need': self::need_page($slug); break; case 'routine': self::routine_page($slug); break; case 'knowledge': self::knowledge_hub(); break; case 'knowledge-topic': self::knowledge_topic($slug); break; case 'knowledge-b2b': self::knowledge_b2b($slug); break; case 'partners': self::partners_sections(); break; case 'distribution': self::distribution_sections(); break; case 'store': self::store_sections(); break; case 'dealer': self::dealer_sections(); break; case 'affiliate': self::affiliate_sections(); break; case 'contact': self::contact_sections(); break;
        }
    }

