    private static function hero(string $eyebrow,string $title,string $lead,string $cta='',string $cta_url='',string $slug=''): void {
        $image=self::hero_image($slug); $style=$image ? ' style="--ddgx-hero:url(\''.esc_url($image).'\')"' : '';
        echo '<section class="ddgx-hero'.($image?' has-image':'').'"'.$style.'><div class="ddgx-hero__veil"></div><div class="ddgx-shell ddgx-hero__inner"><div class="ddgx-hero__copy"><span class="ddgx-kicker">'.esc_html($eyebrow).'</span><h1>'.wp_kses_post($title).'</h1><p>'.esc_html($lead).'</p>';
        if ($cta!=='' && $cta_url!=='') { echo '<a class="ddgx-btn ddgx-btn--light" href="'.esc_url($cta_url).'">'.esc_html($cta).'</a>'; }
        echo '</div><div class="ddgx-hero__seal" aria-hidden="true"><span>ĐD</span><small>BEAUTY<br>ECOSYSTEM</small></div></div></section>';
    }

    private static function hero_image(string $slug): string {
        $id = get_queried_object_id();
        foreach (['_bizrise_ddg_banner_attachment_id','_bizrise_ddg_banner_id','_bizrise_ddg_hero_id','_ddg_banner_id'] as $key) { $aid=(int)get_post_meta($id,$key,true); if ($aid && wp_attachment_is_image($aid)) { $url=wp_get_attachment_image_url($aid,'full'); if ($url) return $url; } }
        $thumb=(int)get_post_thumbnail_id($id); if ($thumb) { $url=wp_get_attachment_image_url($thumb,'full'); if ($url) return $url; }
        if ($slug && isset(self::$brands[$slug])) { $q=new WP_Query(['post_type'=>'attachment','post_status'=>'inherit','post_mime_type'=>'image','posts_per_page'=>1,'fields'=>'ids','s'=>self::$brands[$slug]['name'],'no_found_rows'=>true]); if (!empty($q->posts)) { $url=wp_get_attachment_image_url((int)$q->posts[0],'full'); if ($url) return $url; } }
        return '';
    }

    private static function intro(string $kicker,string $title,string $body=''): void { echo '<section class="ddgx-section"><div class="ddgx-shell ddgx-intro"><span class="ddgx-kicker">'.esc_html($kicker).'</span><h2>'.esc_html($title).'</h2>'; if ($body!=='') echo '<p>'.esc_html($body).'</p>'; echo '</div></section>'; }
    private static function cards(array $items): void { echo '<section class="ddgx-section ddgx-section--tight"><div class="ddgx-shell"><div class="ddgx-cards">'; foreach ($items as $i) { $num=(string)($i[0]??'');$title=(string)($i[1]??'');$text=(string)($i[2]??'');$url=(string)($i[3]??'');$tag=$url!==''?'a':'article';$href=$url!==''?' href="'.esc_url($url).'"':''; echo '<'.$tag.' class="ddgx-card"'.$href.'><span>'.esc_html($num).'</span><h3>'.esc_html($title).'</h3><p>'.esc_html($text).'</p>'.($url!==''?'<b>Khám phá →</b>':'').'</'.$tag.'>'; } echo '</div></div></section>'; }
    private static function steps(array $items): void { echo '<section class="ddgx-section ddgx-section--soft"><div class="ddgx-shell"><div class="ddgx-steps">'; foreach ($items as $i) echo '<div class="ddgx-step"><span>'.esc_html((string)$i[0]).'</span><div><h3>'.esc_html((string)$i[1]).'</h3><p>'.esc_html((string)$i[2]).'</p></div></div>'; echo '</div></div></section>'; }
    private static function split(string $title,string $text,string $cta,string $url,string $slug=''): void { $image=self::find_media($slug); echo '<section class="ddgx-section"><div class="ddgx-shell ddgx-split"><div class="ddgx-split__media">'; if ($image) echo '<img src="'.esc_url($image).'" alt="'.esc_attr($title).'" loading="lazy" decoding="async">'; else echo '<div class="ddgx-art"><span>DDG</span></div>'; echo '</div><div class="ddgx-split__copy"><span class="ddgx-kicker">DISCOVER</span><h2>'.esc_html($title).'</h2><p>'.esc_html($text).'</p><a class="ddgx-link" href="'.esc_url($url).'">'.esc_html($cta).' →</a></div></div></section>'; }
    private static function find_media(string $keyword): string { if ($keyword==='') return ''; $q=new WP_Query(['post_type'=>'attachment','post_status'=>'inherit','post_mime_type'=>'image','posts_per_page'=>1,'fields'=>'ids','s'=>str_replace('-',' ',$keyword),'no_found_rows'=>true]); if (empty($q->posts)) return ''; return (string)(wp_get_attachment_image_url((int)$q->posts[0],'large') ?: ''); }
    private static function cta(string $title,string $text,string $label,string $url): void { echo '<section class="ddgx-cta"><div class="ddgx-shell"><span class="ddgx-kicker">NEXT STEP</span><h2>'.esc_html($title).'</h2><p>'.esc_html($text).'</p><a class="ddgx-btn ddgx-btn--light" href="'.esc_url($url).'">'.esc_html($label).'</a></div></section>'; }

