    private static function routine_hub(): void { self::intro('FIND YOUR ROUTINE','Bắt đầu từ tình huống thật','Không cần biết tên sản phẩm trước. Chọn điều bạn đang quan tâm hoặc cách bạn muốn xây routine.'); self::cards([['01','Dưỡng sáng & đều màu','Bắt đầu từ mục tiêu về vẻ ngoài đều màu và routine nhất quán.',home_url('/duong-sang-deu-mau/')],['02','Chăm sóc da mụn','Tập trung vào routine gọn, dịu và tránh chồng quá nhiều sản phẩm.',home_url('/cham-soc-da-mun/')],['03','Chống nắng','Bảo vệ da là một bước quan trọng trong routine ban ngày.',home_url('/chong-nang/')],['04','Chống lão hóa','Ưu tiên độ ẩm, cảm giác săn chắc và routine có mục tiêu hơn.',home_url('/chong-lao-hoa/')],['05','Chăm sóc body','Biến chăm sóc cơ thể thành một thói quen dễ duy trì.',home_url('/cham-soc-body/')]]); self::cards([['AM','Routine buổi sáng','Gọn, dễ lặp lại và ưu tiên bảo vệ da.',home_url('/routine-buoi-sang/')],['PM','Routine buổi tối','Tập trung làm sạch, chăm sóc và phục hồi cảm giác thoải mái.',home_url('/routine-buoi-toi/')],['START','Starter Routine','Chỉ giữ những bước cần thiết cho người mới.',home_url('/starter-routine/')],['FULL','Complete Routine','Mở rộng khi người dùng đã hiểu rõ nhu cầu và muốn chăm sóc đầy đủ hơn.',home_url('/complete-routine/')]]); }
    private static function need_page(string $slug): void { $titles=['duong-sang-deu-mau'=>'Độ đều màu cần sự nhất quán','cham-soc-da-mun'=>'Routine gọn thường dễ kiểm soát hơn','chong-nang'=>'Bảo vệ da là một thói quen hằng ngày','chong-lao-hoa'=>'Nâng cấp routine khi nhu cầu thay đổi','cham-soc-body'=>'Chăm sóc body cũng cần nhịp điệu']; $texts=['duong-sang-deu-mau'=>'Thay vì liên tục đổi sản phẩm, hãy nhìn lại toàn bộ routine và duy trì những bước có vai trò rõ ràng.','cham-soc-da-mun'=>'Khi da đang có nhiều vấn đề, ưu tiên sự đơn giản, quan sát phản ứng và tránh chồng quá nhiều sản phẩm cùng lúc.','chong-nang'=>'Một routine ban ngày thường cần kết thúc bằng bước bảo vệ phù hợp với bối cảnh sinh hoạt.','chong-lao-hoa'=>'Sau một giai đoạn nhất định, nhiều người bắt đầu chú ý hơn đến độ ẩm, độ đều màu và cảm giác săn chắc.','cham-soc-body'=>'Một vài bước đúng, dễ làm và lặp lại đều đặn thường có giá trị hơn một routine phức tạp.']; self::intro('BEAUTY SITUATION',$titles[$slug]??'Chọn routine phù hợp',$texts[$slug]??'Bắt đầu từ nhu cầu thực tế.'); self::steps([['01','Xác định mục tiêu','Chọn một ưu tiên chính thay vì giải quyết mọi thứ cùng lúc.'],['02','Kiểm tra routine hiện tại','Giữ những bước đang phù hợp, tránh mua trùng chức năng.'],['03','Bổ sung bước còn thiếu','Chỉ thêm sản phẩm khi nó có vai trò rõ trong routine.'],['04','Theo dõi trải nghiệm','Quan sát và điều chỉnh thay vì thay toàn bộ routine quá nhanh.']]); self::cta('Muốn routine gọn nhất?','Bắt đầu bằng Starter Routine trước khi nghĩ đến một bộ đầy đủ.','Starter Routine',home_url('/starter-routine/')); }
    private static function routine_page(string $slug): void { $data=['routine-buoi-sang'=>['Routine buổi sáng','Làm sạch nhẹ nhàng','Chăm sóc mục tiêu','Dưỡng ẩm nếu cần','Bảo vệ da'],'routine-buoi-toi'=>['Routine buổi tối','Làm sạch','Chăm sóc mục tiêu','Dưỡng ẩm','Theo dõi trải nghiệm'],'starter-routine'=>['Starter Routine','Bước nền tảng','Hero product','Một bước hỗ trợ','Giữ routine đơn giản'],'complete-routine'=>['Complete Routine','Làm sạch','Chăm sóc mục tiêu','Bước hỗ trợ','Dưỡng & bảo vệ']]; $d=$data[$slug]??['Routine','Bước 1','Bước 2','Bước 3','Bước 4']; self::intro('ROUTINE BLUEPRINT',$d[0],'Đây là khung logic. Sản phẩm cụ thể chỉ nên được map khi Product Truth và vai trò sử dụng đã được xác minh.'); self::steps([['01',$d[1],'Bắt đầu bằng bước nền tảng phù hợp với thời điểm sử dụng.'],['02',$d[2],'Chọn một sản phẩm có vai trò chính và tránh chồng nhiều mục tiêu.'],['03',$d[3],'Bổ sung nếu routine hiện tại thực sự còn thiếu bước này.'],['04',$d[4],'Giữ routine dễ lặp lại và điều chỉnh dựa trên trải nghiệm thực tế.']]); self::cta('Xem kiến thức cách dùng','Hiểu thứ tự và vai trò từng bước trước khi ghép sản phẩm.','Routine & cách dùng',home_url('/routine-cach-dung/')); }
