    private static function contact_sections(): void { echo '<section class="ddgx-section"><div class="ddgx-shell ddgx-contact"><div><span class="ddgx-kicker">CONTACT CONCIERGE</span><h2>Bạn đang muốn trao đổi về điều gì?</h2><p>Chọn đúng chủ đề giúp yêu cầu được chuyển tới luồng phù hợp nhanh hơn.</p></div><div class="ddgx-contact__grid"><a href="mailto:'.esc_attr((string)get_option('admin_email')).'"><span>01</span><h3>Thương hiệu & sản phẩm</h3><p>Thông tin brand, routine hoặc kênh mua.</p></a><a href="'.esc_url(home_url('/tro-thanh-dai-ly/')).'"><span>02</span><h3>Đại lý & phân phối</h3><p>Nhu cầu hợp tác theo khu vực hoặc hệ thống.</p></a><a href="'.esc_url(home_url('/oem-odm-my-pham/')).'"><span>03</span><h3>OEM / ODM</h3><p>Trao đổi brief và phạm vi phát triển.</p></a><a href="'.esc_url(home_url('/affiliate/')).'"><span>04</span><h3>Affiliate</h3><p>Creator, content partner và social commerce.</p></a></div></div></section>'; }

    private static function css(): string { return <<<'CSS'
.ddgx{--red:#8f1530;--wine:#5e0f22;--ivory:#f8f4ee;--cream:#efe5da;--ink:#211b1c;--muted:#746b6d;--line:rgba(70,38,44,.13);--shadow:0 28px 80px rgba(50,22,28,.12);font-family:"Be Vietnam Pro",system-ui,sans-serif;color:var(--ink);background:#fff}.ddgx *{box-sizing:border-box}.ddgx-shell{width:min(1180px,calc(100% - 40px));margin:auto}.ddgx-hero{position:relative;min-height:clamp(620px,76vh,860px);display:flex;align-items:flex-end;background:linear-gradient(135deg,#6e1027 0%,#9b1937 46%,#c4828f 100%);color:#fff;overflow:hidden}.ddgx-hero.has-image{background-image:linear-gradient(90deg,rgba(37,10,17,.74),rgba(37,10,17,.12)),var(--ddgx-hero);background-size:cover;background-position:center}.ddgx-hero__veil{position:absolute;inset:0;background:radial-gradient(circle at 76% 20%,rgba(255,255,255,.19),transparent 28%),linear-gradient(180deg,transparent 45%,rgba(38,10,18,.3));pointer-events:none}.ddgx-hero__inner{position:relative;z-index:2;display:grid;grid-template-columns:1fr 220px;gap:60px;align-items:end;padding:140px 0 90px}.ddgx-hero__copy{max-width:780px}.ddgx-kicker{display:block;font-size:12px;letter-spacing:.2em;font-weight:700;text-transform:uppercase;margin-bottom:18px}.ddgx-hero h1{font-size:clamp(48px,6vw,84px);line-height:1.02;letter-spacing:-.045em;margin:0 0 24px;font-weight:600}.ddgx-hero p{font-size:clamp(16px,1.5vw,20px);line-height:1.75;max-width:700px;margin:0 0 34px;color:rgba(255,255,255,.88)}.ddgx-hero__seal{width:190px;height:190px;border:1px solid rgba(255,255,255,.38);border-radius:50%;display:grid;place-content:center;text-align:center;backdrop-filter:blur(8px);margin-bottom:10px}.ddgx-hero__seal span{font-size:50px;font-weight:300;letter-spacing:-.08em}.ddgx-hero__seal small{font-size:9px;letter-spacing:.22em;line-height:1.5}.ddgx-btn{display:inline-flex;align-items:center;justify-content:center;min-height:50px;padding:0 26px;border-radius:999px;background:var(--red);color:#fff!important;text-decoration:none!important;font-size:14px;font-weight:700;letter-spacing:.02em;transition:.25s ease}.ddgx-btn:hover{transform:translateY(-2px);box-shadow:0 14px 34px rgba(143,21,48,.22)}.ddgx-btn--light{background:#fff;color:var(--wine)!important}.ddgx-section{padding:100px 0}.ddgx-section--tight{padding-top:20px}.ddgx-section--soft{background:var(--ivory)}.ddgx-intro{max-width:930px}.ddgx-intro h2,.ddgx-section-head h2,.ddgx-split h2,.ddgx-cta h2,.ddgx-contact h2,.ddgx-placeholder h2{font-size:clamp(34px,4vw,58px);line-height:1.08;letter-spacing:-.04em;margin:0 0 22px;font-weight:600}.ddgx-intro p,.ddgx-split p,.ddgx-cta p,.ddgx-contact p,.ddgx-placeholder p{font-size:17px;line-height:1.8;color:var(--muted);max-width:790px}.ddgx-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ddgx-card{min-height:290px;padding:34px;border:1px solid var(--line);border-radius:28px;text-decoration:none!important;color:var(--ink)!important;background:#fff;display:flex;flex-direction:column;transition:.3s ease}.ddgx-card:hover{transform:translateY(-5px);box-shadow:var(--shadow)}.ddgx-card>span{font-size:12px;letter-spacing:.14em;color:var(--red);font-weight:800}.ddgx-card h3{font-size:25px;line-height:1.2;margin:52px 0 13px}.ddgx-card p{color:var(--muted);line-height:1.7;margin:0}.ddgx-card b{margin-top:auto;padding-top:22px;font-size:13px}.ddgx-steps{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line)}.ddgx-step{display:grid;grid-template-columns:70px 1fr;gap:20px;padding:36px 34px;border-bottom:1px solid var(--line)}.ddgx-step:nth-child(odd){border-right:1px solid var(--line)}.ddgx-step>span{color:var(--red);font-size:12px;font-weight:800;letter-spacing:.1em}.ddgx-step h3{font-size:24px;margin:0 0 10px}.ddgx-step p{color:var(--muted);line-height:1.7;margin:0}.ddgx-split{display:grid;grid-template-columns:1.05fr .95fr;gap:70px;align-items:center}.ddgx-split__media{aspect-ratio:4/3;border-radius:34px;overflow:hidden;background:var(--cream)}.ddgx-split__media img{width:100%;height:100%;object-fit:cover}.ddgx-art{width:100%;height:100%;display:grid;place-items:center;background:linear-gradient(135deg,#eee2d6,#d5a5ad)}.ddgx-art span{font-size:100px;color:rgba(143,21,48,.19);font-weight:200}.ddgx-link{display:inline-block;margin-top:16px;color:var(--red)!important;font-weight:800;text-decoration:none!important}.ddgx-section-head{margin-bottom:36px}.ddgx-brand-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ddgx-brand{padding:34px;min-height:360px;background:#fff;border-radius:30px;text-decoration:none!important;color:var(--ink)!important;display:flex;flex-direction:column;border:1px solid var(--line);transition:.3s}.ddgx-brand:hover{transform:translateY(-5px);box-shadow:var(--shadow)}.ddgx-brand i{width:36px;height:5px;border-radius:9px;background:var(--accent);margin-bottom:50px}.ddgx-brand>span{font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:var(--accent);font-weight:800}.ddgx-brand h3{font-size:31px;margin:10px 0 14px}.ddgx-brand p{color:var(--muted);line-height:1.7}.ddgx-brand b{margin-top:auto;font-size:13px}.ddgx-articles{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.ddgx-articles a{padding:30px;background:#fff;border-radius:24px;color:var(--ink)!important;text-decoration:none!important}.ddgx-articles small{color:var(--red)}.ddgx-articles h3{font-size:22px;line-height:1.3}.ddgx-articles p{color:var(--muted);line-height:1.65}.ddgx-articles b{font-size:13px}.ddgx-cta{padding:100px 0;background:linear-gradient(135deg,#5e0f22,#8f1530);color:#fff;text-align:center}.ddgx-cta .ddgx-shell{max-width:820px}.ddgx-cta p{margin:0 auto 32px;color:rgba(255,255,255,.78)}.ddgx-contact{display:grid;grid-template-columns:.8fr 1.2fr;gap:60px}.ddgx-contact__grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.ddgx-contact__grid a{padding:28px;border:1px solid var(--line);border-radius:24px;text-decoration:none!important;color:var(--ink)!important}.ddgx-contact__grid span{font-size:11px;color:var(--red);font-weight:800}.ddgx-contact__grid h3{font-size:20px}.ddgx-contact__grid p{font-size:14px;line-height:1.6}.ddgx-placeholder{padding:56px;border-radius:30px;background:var(--ivory);text-align:center}.ddgx-placeholder>span{font-size:11px;letter-spacing:.18em;color:var(--red);font-weight:800}.ddgx-placeholder p{margin:0 auto 28px}.ddgx--brand .ddgx-hero{min-height:720px}@media(max-width:900px){.ddgx-shell{width:min(100% - 28px,1180px)}.ddgx-hero{min-height:78vh}.ddgx-hero__inner{grid-template-columns:1fr;padding:110px 0 62px}.ddgx-hero__seal{display:none}.ddgx-hero h1{font-size:clamp(42px,12vw,64px)}.ddgx-section{padding:72px 0}.ddgx-cards,.ddgx-brand-grid,.ddgx-articles{grid-template-columns:1fr 1fr}.ddgx-split,.ddgx-contact{grid-template-columns:1fr;gap:36px}.ddgx-steps{grid-template-columns:1fr}.ddgx-step:nth-child(odd){border-right:0}.ddgx-contact__grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.ddgx-hero{min-height:82svh;background-position:center}.ddgx-hero__inner{padding:120px 0 48px}.ddgx-hero p{font-size:16px;line-height:1.7}.ddgx-section{padding:58px 0}.ddgx-cards,.ddgx-brand-grid,.ddgx-articles,.ddgx-contact__grid{grid-template-columns:1fr}.ddgx-card{min-height:240px;padding:28px}.ddgx-card h3{margin-top:38px}.ddgx-brand{min-height:300px}.ddgx-split__media{aspect-ratio:3/4}.ddgx-step{grid-template-columns:48px 1fr;padding:28px 12px}.ddgx-intro h2,.ddgx-section-head h2,.ddgx-split h2,.ddgx-cta h2,.ddgx-contact h2,.ddgx-placeholder h2{font-size:34px}.ddgx-cta{padding:70px 0}}
CSS; }
}

